// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

export interface BloodCenterReturnOut {
  date_from: string;
  date_to: string;
  /** Different donors attending */
  donors: number;
  collections: number;
  donations_by_status: CenterStatusCountOut[];
  collections_by_kind: CenterKindCountOut[];
  deferrals_by_kind: CenterDeferralCountOut[];
  /** The five mandatory screens, each listed */
  infections: CenterInfectionOut[];
  components_produced: CenterComponentCountOut[];
  components_released: CenterComponentCountOut[];
  components_discarded: CenterDiscardCountOut[];
  /** Collections none of which reached the blood bank (the Act s.12(b)) */
  whole_blood_not_used: number;
  donor_reactions: CenterDonorReactionCountOut[];
  /** Adverse transfusion reactions in patients, all sources */
  patient_reactions: CenterPatientReactionCountOut[];
}

export interface CenterStatusCountOut {
  status: "Accepted" | "Deferred" | "Collected" | "Unsuccessful" | "Cleared" | "Reactive" | "Rejected";
  n: number;
}

export interface CenterKindCountOut {
  donation_kind: "Voluntary" | "Replacement" | "Autologous";
  n: number;
}

export interface CenterDeferralCountOut {
  kind: "Temporary" | "Permanent";
  n: number;
}

export interface CenterInfectionOut {
  marker: "HBsAg" | "AntiHCV" | "AntiHIV" | "Syphilis" | "Malaria" | "ABOForward" | "ABOReverse" | "RhD";
  /** Donations with a reactive first test */
  reactive: number;
  /** Donations reactive again on the repeat */
  repeat_reactive: number;
}

export interface CenterComponentCountOut {
  component: "WholeBlood" | "RedCells" | "FreshFrozenPlasma" | "Cryoprecipitate" | "Platelets";
  n: number;
}

export interface CenterDiscardCountOut {
  discard_reason: "ReactiveScreening" | "DonationRejected" | "BagDamaged" | "Expired" | "ProcessingTimeExceeded" | "QualityControl" | "DonorInformation" | "Other";
  n: number;
}

export interface CenterDonorReactionCountOut {
  reaction: "None" | "Vasovagal" | "Haematoma" | "Convulsions" | "Vomiting" | "Tetany" | "LocalAllergic" | "Severe" | "Other";
  n: number;
}

export interface CenterPatientReactionCountOut {
  reaction_class: "Haemolytic" | "Anaphylactic" | "DelayedHaemolytic" | "Bacterial" | "Other";
  n: number;
}

